package com.kernel.ai.core.voice.asr4all

import com.kernel.ai.core.executorch.TensorDType
import java.io.File
import java.nio.file.Files
import org.junit.jupiter.api.AfterEach
import org.junit.jupiter.api.Assertions.assertEquals
import org.junit.jupiter.api.Test
import org.junit.jupiter.api.assertThrows

/**
 * Reads `:core:executorch`'s committed smoke program (generated by
 * `core/executorch/tools/generate_smoke_pte.py`). The expected method I/O is what the official
 * `executorch` 1.5.1 Python runtime's MethodMeta reports for the same file.
 */
class PteMethodTableTest {
    private val smoke = File("../executorch/src/androidTest/assets/executorch_smoke.pte")
    private val temporary = mutableListOf<File>()

    @AfterEach
    fun cleanup() {
        temporary.forEach(File::delete)
    }

    @Test
    fun `smoke program declares its methods' inputs and outputs`() {
        val table = PteMethodTable.read(smoke)

        assertEquals(setOf("forward", "triple"), table.keys)
        assertEquals(
            PteMethodInfo(
                inputs = listOf(PteTensorInfo(TensorDType.FLOAT32, listOf(1, 4), dynamic = false)),
                outputs = listOf(PteTensorInfo(TensorDType.FLOAT32, listOf(1, 3), dynamic = false)),
            ),
            table["forward"],
        )
        assertEquals(listOf(TensorDType.INT64), table.getValue("triple").inputs.map { it?.dtype })
        assertEquals(listOf(listOf(2L)), table.getValue("triple").inputs.map { it?.sizes })
        assertEquals(listOf(TensorDType.INT64), table.getValue("triple").outputs.map { it?.dtype })
    }

    @Test
    fun `garbage and truncated files are config errors`() {
        val garbage = temp(ByteArray(64) { 7 })
        val truncated = temp(smoke.readBytes().copyOf(200))

        assertThrows<Asr4AllConfigException> { PteMethodTable.read(garbage) }
        assertThrows<Asr4AllConfigException> { PteMethodTable.read(truncated) }
    }

    private fun temp(bytes: ByteArray): File =
        Files.createTempFile("pte", ".pte").toFile().also { it.writeBytes(bytes); temporary += it }
}
